CREATE FUNCTION public.plm_register_file(_revision uuid,_path text,_name text,_mime text,_size bigint,_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.plm_revisions; fid uuid; BEGIN SELECT * INTO r FROM public.plm_revisions WHERE id=_revision FOR UPDATE; IF NOT FOUND OR NOT public.plm_has_scope(r.organization_id,r.site_id) THEN RAISE EXCEPTION 'Unauthorized file scope'; END IF; IF r.state<>'DRAFT' OR (SELECT kind FROM public.plm_entities WHERE id=r.entity_id)<>'DOCUMENT' THEN RAISE EXCEPTION 'File attaches only to a draft document revision'; END IF; IF _path NOT LIKE auth.uid()::text||'/%' THEN RAISE EXCEPTION 'Upload ownership mismatch'; END IF; IF _size<=0 OR _size>20971520 OR _mime NOT IN ('application/pdf','image/png','image/jpeg') OR _hash!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Unsupported file, size or SHA-256 hash'; END IF; IF length(_name) NOT BETWEEN 1 AND 255 THEN RAISE EXCEPTION 'Original filename required'; END IF; INSERT INTO public.plm_document_files(revision_id,organization_id,site_id,storage_path,original_name,mime_type,size_bytes,sha256,uploaded_by) VALUES(_revision,r.organization_id,r.site_id,_path,_name,_mime,_size,_hash,auth.uid()) RETURNING id INTO fid; INSERT INTO public.plm_audit_events(organization_id,site_id,actor_id,action,revision_id,reason,after_value,content_hash) VALUES(r.organization_id,r.site_id,auth.uid(),'REGISTER_FILE',r.id,'Server-verified immutable controlled file',jsonb_build_object('file_id',fid,'sha256',_hash,'size',_size),r.content_hash); RETURN fid; END $$;
REVOKE ALL ON FUNCTION public.plm_register_file(uuid,text,text,text,bigint,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.plm_register_file(uuid,text,text,text,bigint,text) TO service_role;
CREATE FUNCTION public.plm_receive_ack(_body jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ev public.plm_outbox; prior public.plm_inbox; outcome text; why text; consumer text:=_body->>'consumer'; BEGIN SELECT * INTO ev FROM public.plm_outbox WHERE id=(_body->>'eventId')::uuid AND organization_id=(_body->>'organizationId')::uuid AND site_id IS NOT DISTINCT FROM nullif(_body->>'siteId','')::uuid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Event not found in connector scope'; END IF; IF NOT EXISTS(SELECT 1 FROM public.plm_delivery_attempts WHERE event_id=ev.id AND consumer=plm_receive_ack.consumer) THEN RAISE EXCEPTION 'Consumer not requested'; END IF; SELECT * INTO prior FROM public.plm_inbox WHERE event_id=ev.id AND plm_inbox.consumer=plm_receive_ack.consumer; IF _body->>'contentHash' IS DISTINCT FROM ev.content_hash OR (_body->>'revisionId')::uuid<>ev.revision_id OR (_body->>'sourceTimestamp')::timestamptz<ev.occurred_at OR (_body->>'sourceTimestamp')::timestamptz>now()+interval '5 minutes' THEN outcome:='QUARANTINED'; why:='Modified, stale or out-of-order acknowledgement'; ELSIF prior.id IS NOT NULL THEN outcome:=CASE WHEN prior.content_hash=_body->>'contentHash' AND prior.status=_body->>'status' THEN 'DUPLICATE' ELSE 'QUARANTINED' END; why:='Repeated acknowledgement; original evidence retained'; ELSE outcome:=_body->>'status'; why:=_body->>'reason'; IF outcome NOT IN ('BUSINESS_ACCEPTED','REJECTED') THEN RAISE EXCEPTION 'Explicit business outcome required'; END IF; END IF; INSERT INTO public.plm_inbound_attempts(organization_id,site_id,event_id,consumer,content_hash,outcome,reason) VALUES(ev.organization_id,ev.site_id,ev.id,consumer,_body->>'contentHash',outcome,why); IF prior.id IS NULL THEN INSERT INTO public.plm_inbox(organization_id,site_id,event_id,consumer,revision_id,content_hash,status,reason,source_timestamp) VALUES(ev.organization_id,ev.site_id,ev.id,consumer,ev.revision_id,_body->>'contentHash',outcome,why,(_body->>'sourceTimestamp')::timestamptz); END IF; RETURN outcome; END $$;
REVOKE ALL ON FUNCTION public.plm_receive_ack(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.plm_receive_ack(jsonb) TO service_role;
CREATE FUNCTION public.plm_guard_bound_references() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE k text; x text; linked public.plm_revisions; result jsonb; BEGIN SELECT kind INTO k FROM public.plm_entities WHERE id=NEW.entity_id; IF TG_OP='UPDATE' AND (NEW.entity_id IS DISTINCT FROM OLD.entity_id OR NEW.organization_id IS DISTINCT FROM OLD.organization_id OR NEW.site_id IS DISTINCT FROM OLD.site_id OR NEW.item_revision_id IS DISTINCT FROM OLD.item_revision_id OR NEW.revision_label IS DISTINCT FROM OLD.revision_label) THEN RAISE EXCEPTION 'Stable identity and scope cannot be changed'; END IF; IF NEW.item_revision_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.plm_revisions r WHERE r.id=NEW.item_revision_id AND r.organization_id=NEW.organization_id AND (r.site_id IS NULL OR r.site_id IS NOT DISTINCT FROM NEW.site_id)) THEN RAISE EXCEPTION 'Item reference outside scope'; END IF; IF NEW.payload ? 'revisionIds' THEN FOR x IN SELECT value FROM jsonb_array_elements_text(NEW.payload->'revisionIds') LOOP SELECT * INTO linked FROM public.plm_revisions WHERE id=x::uuid AND organization_id=NEW.organization_id AND (site_id IS NULL OR site_id IS NOT DISTINCT FROM NEW.site_id); IF NOT FOUND THEN RAISE EXCEPTION 'Manifest reference outside scope'; END IF; END LOOP; END IF; IF NEW.state='RELEASED' AND (TG_OP='INSERT' OR OLD.state<>'RELEASED') THEN IF k='DOCUMENT' AND NOT EXISTS(SELECT 1 FROM public.plm_document_files WHERE revision_id=NEW.id) THEN RAISE EXCEPTION 'Verified immutable document file required'; END IF; IF k='ITEM' AND NEW.payload->>'makeBuy'='MAKE' AND (NOT EXISTS(SELECT 1 FROM public.plm_revisions r JOIN public.plm_entities e ON e.id=r.entity_id WHERE r.item_revision_id=NEW.id AND e.kind='ROUTING' AND r.state='RELEASED') OR NOT EXISTS(SELECT 1 FROM public.plm_revisions r JOIN public.plm_entities e ON e.id=r.entity_id WHERE r.item_revision_id=NEW.id AND e.kind='BOM' AND r.state='RELEASED')) THEN RAISE EXCEPTION 'Manufactured item release requires compatible released BOM and route'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER plm_reference_guard BEFORE INSERT OR UPDATE ON public.plm_revisions FOR EACH ROW EXECUTE FUNCTION public.plm_guard_bound_references();